'use client';

import { useId, useLayoutEffect, useRef, useState, type KeyboardEvent, type ReactNode } from 'react';
import { motion, useReducedMotion } from 'motion/react';
import './selectable-cards.css';

export interface SelectableCardOption {
  value: string;
  label: string;
  description?: ReactNode;
  icon?: ReactNode;
  preview?: ReactNode;
  disabled?: boolean;
}
export interface SelectableCardsProps {
  options: readonly SelectableCardOption[];
  value: string | null;
  onValueChange: (value: string) => void;
  label: string;
  /** Optional native form entry. No input is submitted for a disabled selection. */
  name?: string;
  disabled?: boolean;
  className?: string;
}

/** Selection belongs to the caller. Pointer hover never changes the chosen value. */
export function SelectableCards({ options, value, onValueChange, label, name, disabled = false, className = '' }: SelectableCardsProps) {
  const uid = useId();
  const [hovered, setHovered] = useState<string | null>(null);
  const [hoverRect, setHoverRect] = useState<{ x: number; y: number; width: number; height: number } | null>(null);
  const root = useRef<HTMLDivElement>(null);
  const refs = useRef(new Map<string, HTMLButtonElement>());
  const lastHovered = useRef<string | null>(null);
  const reduced = useReducedMotion();
  const enabled = options.filter(option => !disabled && !option.disabled);
  const tabValue = enabled.find(option => option.value === value)?.value ?? enabled[0]?.value;
  const hoverValue = enabled.some(option => option.value === hovered) ? hovered : null;
  const selected = options.find(option => option.value === value);
  useLayoutEffect(() => {
    if (hoverValue) lastHovered.current = hoverValue;
    // Keep the fading surface measured when the viewport changes after leaving.
    const slot = lastHovered.current ? refs.current.get(lastHovered.current)?.parentElement : null;
    if (!slot || !root.current) { setHoverRect(null); return; }
    const measure = () => setHoverRect({ x: slot.offsetLeft, y: slot.offsetTop, width: slot.offsetWidth, height: slot.offsetHeight });
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(root.current);
    observer.observe(slot);
    return () => observer.disconnect();
  }, [hoverValue]);
  function navigate(event: KeyboardEvent<HTMLButtonElement>, current: string) {
    let next: number;
    const index = enabled.findIndex(option => option.value === current);
    switch (event.key) {
      case 'ArrowRight': next = (index + 1) % enabled.length; break;
      case 'ArrowLeft': next = (index + enabled.length - 1) % enabled.length; break;
      case 'ArrowDown': next = (index + 1) % enabled.length; break;
      case 'ArrowUp': next = (index + enabled.length - 1) % enabled.length; break;
      case 'Home': next = 0; break;
      case 'End': next = enabled.length - 1; break;
      default: return;
    }
    event.preventDefault();
    const target = enabled[next];
    refs.current.get(target.value)?.focus();
    if (target.value !== value) onValueChange(target.value);
  }
  return <div ref={root} role="radiogroup" aria-label={label} aria-disabled={disabled || undefined} className={`mf-selectable-cards ${className}`} onPointerLeave={() => setHovered(null)}>
      {hoverRect && <motion.span aria-hidden="true" className="mf-selectable-cards__hover"
        initial={{ ...hoverRect, opacity: 0 }} animate={{ ...hoverRect, opacity: hoverValue ? 1 : 0 }}
        transition={reduced ? { duration: 0 } : { type: 'spring', stiffness: 450, damping: 36, opacity: { duration: .13 } }} />}
      {name && selected && <input type="hidden" name={name} value={selected.value} disabled={disabled || selected.disabled} />}
      {options.map(option => {
        const checked = option.value === value;
        const unavailable = disabled || option.disabled;
        return <div className="mf-selectable-cards__slot" key={option.value}>
          <button type="button" role="radio" aria-checked={checked} aria-labelledby={`${uid}-${option.value}-label`}
            aria-describedby={option.description ? `${uid}-${option.value}-description` : undefined}
            disabled={unavailable} tabIndex={!unavailable && tabValue === option.value ? 0 : -1}
            className="mf-selectable-cards__card" data-selected={checked}
            ref={element => { if (element) refs.current.set(option.value, element); else refs.current.delete(option.value); }}
            onPointerEnter={event => { if (event.pointerType !== 'touch') setHovered(unavailable ? null : option.value); }}
            onKeyDown={event => navigate(event, option.value)}
            onClick={() => { if (!checked) onValueChange(option.value); }}>
            <span className="mf-selectable-cards__top">
              {option.preview ? <span aria-hidden="true" className="mf-selectable-cards__preview">{option.preview}</span> : option.icon ? <span aria-hidden="true" className="mf-selectable-cards__icon">{option.icon}</span> : <span/>}
              <span aria-hidden="true" className="mf-selectable-cards__check"><svg viewBox="0 0 16 16" fill="none"><path d="m4 8 2.5 2.5L12 5" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round"/></svg></span>
            </span>
            <span id={`${uid}-${option.value}-label`} className="mf-selectable-cards__label">{option.label}</span>
            {option.description && <span id={`${uid}-${option.value}-description`} className="mf-selectable-cards__description">{option.description}</span>}
          </button>
        </div>;
      })}
    </div>;
}

.mf-selectable-cards{position:relative;isolation:isolate;display:grid;grid-template-columns:repeat(auto-fit,minmax(min(144px,100%),1fr));gap:5px;width:100%;min-width:0;color:#f4f4f5;font-family:inherit}
.mf-selectable-cards,.mf-selectable-cards *{box-sizing:border-box}
.mf-selectable-cards__slot{position:relative;padding:5px;display:flex;min-width:0}
.mf-selectable-cards__hover{position:absolute;left:0;top:0;border-radius:15px;background:#e4e4e7;pointer-events:none;z-index:0}
.mf-selectable-cards__card{position:relative;z-index:1;appearance:none;display:flex;flex:1;min-width:0;flex-direction:column;align-items:stretch;gap:9px;padding:15px;text-align:left;background:#000;color:inherit;border:1px solid transparent;border-radius:11px;box-shadow:none;cursor:pointer;font:inherit;transition:background-color 150ms ease,border-color 150ms ease,box-shadow 150ms ease}
.mf-selectable-cards__card:hover:not(:disabled):not([data-selected="true"]){border-color:oklch(.372 .044 257.287)}
.mf-selectable-cards__card[data-selected="true"]{background:#000;border-color:#f4f4f5;box-shadow:0 0 0 1px #52525b}
.mf-selectable-cards__card:focus-visible{outline:2px solid #71717a;outline-offset:4px}
.mf-selectable-cards__card:disabled{color:#a1a1aa;cursor:not-allowed;background:#27272a;box-shadow:none}
.mf-selectable-cards__card[data-selected="true"]:disabled{border-color:#a1a1aa;box-shadow:0 0 0 1px #71717a}
.mf-selectable-cards__top{display:flex;justify-content:space-between;align-items:center;gap:10px;min-height:28px;margin-bottom:3px}
.mf-selectable-cards__icon{display:grid;place-items:center;width:28px;height:28px;color:#d4d4d8}
.mf-selectable-cards__icon svg{width:24px;height:24px}
.mf-selectable-cards__preview{display:grid;place-items:center;min-width:0;flex:1;height:56px;overflow:hidden;border-radius:6px}
.mf-selectable-cards__preview>svg{display:block;width:100%;height:100%}
.mf-selectable-cards__check{display:grid;place-items:center;width:18px;height:18px;border:1px solid #71717a;border-radius:50%;color:#fff;background:transparent;transition:background-color 150ms ease,border-color 150ms ease}
.mf-selectable-cards__check svg{width:14px;height:14px;opacity:0;transition:opacity 120ms ease}
.mf-selectable-cards__card[data-selected="true"] .mf-selectable-cards__check{background:#f4f4f5;border-color:#f4f4f5;color:#000}
.mf-selectable-cards__card[data-selected="true"] .mf-selectable-cards__check svg{opacity:1}
.mf-selectable-cards__label{font-size:13px;font-weight:600;line-height:1.35;overflow-wrap:anywhere}
.mf-selectable-cards__description{font-size:12px;font-weight:400;line-height:1.5;color:#a1a1aa;overflow-wrap:anywhere}
@media(max-width:480px){.mf-selectable-cards{grid-template-columns:1fr}.mf-selectable-cards__card{display:grid;grid-template-columns:56px 1fr;column-gap:14px;padding:14px}.mf-selectable-cards__top{grid-column:1;grid-row:1 / 3;display:contents}.mf-selectable-cards__icon,.mf-selectable-cards__preview{grid-column:1;grid-row:1 / 3;align-self:center}.mf-selectable-cards__preview{height:42px}.mf-selectable-cards__check{grid-column:3;grid-row:1 / 3;align-self:center}.mf-selectable-cards__label,.mf-selectable-cards__description{grid-column:2}.mf-selectable-cards__description{grid-row:2}}
@media(prefers-reduced-motion:reduce){.mf-selectable-cards__card,.mf-selectable-cards__check,.mf-selectable-cards__check svg{transition:none}}
